"{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://github.com/creative-world/schema/canon-node.schema.json\",\n  \"title\": \"Canon node\",\n  \"description\": \"One row of the canon register: a named thing the Atlas can point to. Stored as CSV (one file per family), one schema for every kind. Generated from codes.py; do not edit by hand.\",\n  \"type\": \"object\",\n  \"required\": [\n    \"id\",\n    \"name\",\n    \"kind\",\n    \"world\",\n    \"tier\",\n    \"confidence\"\n  ],\n  \"additionalProperties\": false,\n  \"properties\": {\n    \"id\": {\n      \"type\": \"string\",\n      \"pattern\": \"^(ARC|BEL|CIV|COM|DIA|DYN|EVT|GAP|HOR|INS|INV|ISP|MAT|MKR|MOV|NET|OBT|OCC|PER|PLC|POL|PRA|PRD|SCH|STY|TEC)[0-9]{3}$\",\n      \"description\": \"Prefix names the family; see x-prefixes.\"\n    },\n    \"name\": {\n      \"type\": \"string\",\n      \"minLength\": 1,\n      \"description\": \"The community's own name first where one exists.\"\n    },\n    \"other_names\": {\n      \"type\": \"string\",\n      \"description\": \"Exonyms, spellings, older names. Several values are separated by semicolons.\"\n    },\n    \"kind\": {\n      \"enum\": [\n        \"archaeological-culture\",\n        \"belief-tradition\",\n        \"civilisation-as-commonly-named\",\n",
"        \"community\",\n        \"diaspora\",\n        \"dynasty\",\n        \"event\",\n        \"first-known\",\n        \"horizon\",\n        \"institution\",\n        \"interaction-sphere\",\n        \"living-practice\",\n        \"maker-community\",\n        \"material\",\n        \"movement\",\n        \"network\",\n        \"object-type\",\n        \"period\",\n        \"person\",\n        \"place\",\n        \"polity\",\n        \"school\",\n        \"style\",\n        \"technique\"\n      ]\n    },\n    \"family\": {\n      \"type\": \"string\",\n      \"description\": \"Grouping family within the kind (e.g. 'Andes', 'porcelain').\"\n    },\n    \"world\": {\n      \"enum\": [\n        \"F1.10\",\n        \"F1.11\",\n        \"F1.12\",\n        \"F1.12a\",\n        \"F1.13\",\n        \"F1.6\",\n        \"F1.7\",\n        \"F1.8\",\n        \"F1.9\",\n        \"F1.9a\",\n        \"THEME\"\n      ],\n      \"description\": \"The F1 world chapter that carries the node, or THEME.\"\n    },\n    \"sub_regions\": {\n      \"type\": \"string\",\n      \"description\": \"Codes from x-sub-regions. Several values are separated by semicolons.\"\n    },\n    \"start\": {\n      \"type\": [\n        \"integer\",\n        \"string\"\n      ],\n      \"description\": \"Signed year, BCE negative; empty if unknown.\"\n    },\n    \"end\": {\n",
"      \"type\": [\n        \"integer\",\n        \"string\"\n      ],\n      \"description\": \"Signed year; empty for ongoing.\"\n    },\n    \"date_note\": {\n      \"type\": \"string\",\n      \"description\": \"The source's own qualifier: 'about', 'by', 'contested'.\"\n    },\n    \"making_significance\": {\n      \"type\": \"string\",\n      \"description\": \"Why it matters for making, one or two sentences.\"\n    },\n    \"materials_techniques\": {\n      \"type\": \"string\",\n      \"description\": \"Several values are separated by semicolons.\"\n    },\n    \"object_types\": {\n      \"type\": \"string\",\n      \"description\": \"Several values are separated by semicolons.\"\n    },\n    \"functions\": {\n      \"type\": \"string\",\n      \"description\": \"From x-functions. Several values are separated by semicolons.\"\n    },\n    \"defined_by\": {\n      \"type\": \"string\",\n      \"description\": \"Who drew the grouping, and when (a period or label is a definition by a source).\"\n    },\n    \"leaves_out\": {\n      \"type\": \"string\",\n      \"description\": \"What the name or grouping leaves out. Required for civilisations, polities and movements.\"\n    },\n    \"sensitivity\": {\n      \"type\": \"string\",\n",
"      \"description\": \"From x-sensitivity. Several values are separated by semicolons.\"\n    },\n    \"free_sources\": {\n      \"type\": \"string\",\n      \"description\": \"Zero-cost routes to read or show it. Several values are separated by semicolons.\"\n    },\n    \"tier\": {\n      \"enum\": [\n        \"R1\",\n        \"R2\",\n        \"R3\"\n      ],\n      \"description\": \"R1 walk; R2 card with member grid; R3 card with link.\"\n    },\n    \"units\": {\n      \"type\": \"string\",\n      \"description\": \"Units that use it, e.g. F1.6; F1.14. Several values are separated by semicolons.\"\n    },\n    \"confidence\": {\n      \"enum\": [\n        \"high\",\n        \"low\",\n        \"medium\"\n      ]\n    },\n    \"notes\": {\n      \"type\": \"string\"\n    }\n  },\n  \"allOf\": [\n    {\n      \"if\": {\n        \"properties\": {\n          \"kind\": {\n            \"enum\": [\n              \"civilisation-as-commonly-named\",\n              \"polity\",\n              \"movement\"\n            ]\n          }\n        }\n      },\n      \"then\": {\n        \"required\": [\n          \"leaves_out\"\n        ],\n        \"properties\": {\n          \"leaves_out\": {\n            \"minLength\": 1\n          }\n        }\n      }\n    }\n  ],\n  \"x-column-order\": [\n    \"id\",\n    \"name\",\n",
"    \"other_names\",\n    \"kind\",\n    \"family\",\n    \"world\",\n    \"sub_regions\",\n    \"start\",\n    \"end\",\n    \"date_note\",\n    \"making_significance\",\n    \"materials_techniques\",\n    \"object_types\",\n    \"functions\",\n    \"defined_by\",\n    \"leaves_out\",\n    \"sensitivity\",\n    \"free_sources\",\n    \"tier\",\n    \"units\",\n    \"confidence\",\n    \"notes\"\n  ],\n  \"x-prefixes\": {\n    \"CIV\": [\n      \"civilisation-as-commonly-named\"\n    ],\n    \"ARC\": [\n      \"archaeological-culture\"\n    ],\n    \"HOR\": [\n      \"horizon\"\n    ],\n    \"ISP\": [\n      \"interaction-sphere\"\n    ],\n    \"POL\": [\n      \"polity\"\n    ],\n    \"DYN\": [\n      \"dynasty\"\n    ],\n    \"BEL\": [\n      \"belief-tradition\"\n    ],\n    \"MOV\": [\n      \"movement\"\n    ],\n    \"STY\": [\n      \"style\"\n    ],\n    \"SCH\": [\n      \"school\"\n    ],\n    \"MKR\": [\n      \"maker-community\"\n    ],\n    \"INS\": [\n      \"institution\"\n    ],\n    \"EVT\": [\n      \"event\"\n    ],\n    \"OCC\": [\n      \"event\"\n    ],\n    \"NET\": [\n      \"network\"\n    ],\n    \"DIA\": [\n      \"diaspora\"\n    ],\n    \"TEC\": [\n      \"technique\"\n    ],\n    \"MAT\": [\n      \"material\"\n    ],\n    \"OBT\": [\n      \"object-type\"\n    ],\n    \"PRA\": [\n      \"living-practice\"\n    ],\n    \"INV\": [\n      \"first-known\"\n",
"    ],\n    \"COM\": [\n      \"community\"\n    ],\n    \"PER\": [\n      \"person\"\n    ],\n    \"PLC\": [\n      \"place\"\n    ],\n    \"PRD\": [\n      \"period\"\n    ],\n    \"GAP\": [\n      \"event\",\n      \"institution\",\n      \"maker-community\",\n      \"movement\",\n      \"network\",\n      \"object-type\",\n      \"style\",\n      \"technique\"\n    ]\n  },\n  \"x-sub-regions\": {\n    \"AF-EGY\": \"Egypt\",\n    \"AF-NUB\": \"Nubia and Sudan\",\n    \"AF-MAG\": \"Maghrib\",\n    \"AF-SAH\": \"Sahel and Western Sudan\",\n    \"AF-GUI\": \"Guinea Coast\",\n    \"AF-CEN\": \"Central Africa\",\n    \"AF-HRN\": \"Ethiopia and the Horn\",\n    \"AF-SWA\": \"Swahili coast and East African interior\",\n    \"AF-SOU\": \"Southern Africa\",\n    \"AF-MAD\": \"Madagascar and Indian Ocean islands\",\n    \"AM-ARC\": \"Arctic\",\n    \"AM-NWC\": \"Northwest Coast\",\n    \"AM-WST\": \"North American West\",\n    \"AM-EWD\": \"Eastern Woodlands\",\n    \"AM-MES\": \"Mesoamerica\",\n    \"AM-CAM\": \"Central America\",\n    \"AM-CAR\": \"Caribbean\",\n    \"AM-AND\": \"Andes and Pacific coast\",\n    \"AM-AMZ\": \"Amazonia and lowland South America\",\n    \"AM-LAT\": \"Colonial and modern Latin America\",\n    \"AS-CHN\": \"China\",\n    \"AS-KOR\": \"Korea\",\n    \"AS-JPN\": \"Japan\",\n    \"AS-SAS\": \"South Asia\",\n",
