"{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://github.com/creative-world/schema/concept-dna.schema.json\",\n  \"title\": \"Concept DNA\",\n  \"description\": \"The one artifact every learner builds. Each unit writes entries into named fields; the app holds the artifact as this structure. Field list from Master Structure v2.1, 'The artifact schema'.\",\n  \"type\": \"object\",\n  \"required\": [\n    \"learner_world\",\n    \"fields\"\n  ],\n  \"properties\": {\n    \"learner_world\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"title\",\n        \"kind\"\n      ],\n      \"properties\": {\n        \"title\": {\n          \"type\": \"string\"\n        },\n        \"kind\": {\n          \"enum\": [\n            \"own\",\n            \"seed\"\n          ]\n        },\n        \"seed\": {\n          \"enum\": [\n            \"Salt Road\",\n            \"Night Library\",\n            \"Second Skin\"\n          ]\n        },\n        \"route\": {\n          \"enum\": [\n            \"Maker\",\n            \"Briefer\",\n            \"Founder\",\n            \"Student\"\n          ]\n        }\n      }\n    },\n    \"fields\": {\n      \"type\": \"object\",\n      \"additionalProperties\": false,\n      \"properties\": {\n        \"PRM\": {\n",
"          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Premise: proposition, stance, contradiction, scenario, non-goals. Filled mainly by M1.\"\n        },\n        \"PER\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Perimeter: what the world enables, protects, resists, rejects, transforms. Filled mainly by F5, M1.\"\n        },\n        \"RUL\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Rules: constants, variables, thresholds. Filled mainly by M2.\"\n        },\n        \"ANT\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Anti-DNA. Filled mainly by M2.\"\n        },\n        \"ALN\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Alignment with practice, collection and masterbrand DNA. Filled mainly by M2, R1.\"\n        },\n        \"OBL\": {\n          \"type\": \"array\",\n          \"items\": {\n",
"            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Category obligations and permitted variation. Filled mainly by M2.\"\n        },\n        \"TST\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Test set: belongs, edge, failure, seductive-but-off. Filled mainly by M2, every module's closing test.\"\n        },\n        \"BRF\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Contributor brief and agent prompt architecture. Filled mainly by M2, T3.\"\n        },\n        \"VER\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Version history and change log. Filled mainly by M2 onward.\"\n        },\n        \"COL\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Collection map: roles, families, drops, carriers, distribution. Filled mainly by M3.\"\n        },\n        \"ANC\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n",
"          \"description\": \"Anchor expression and family. Filled mainly by M4, areas.\"\n        },\n        \"ADJ\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Adjacent translation. Filled mainly by M4, areas.\"\n        },\n        \"JDG\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Judged set (briefer lane). Filled mainly by Every module's closing test, briefer lane.\"\n        },\n        \"CMB\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Commissioning brief and record (briefer lane). Filled mainly by Areas, R3.\"\n        },\n        \"VEN\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Venture: masterbrand, orbital architecture, community, campaign. Filled mainly by R1.\"\n        },\n        \"RGT\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n",
"          \"description\": \"Rights and money: IP protocol, funding scenario, cash model. Filled mainly by R2.\"\n        },\n        \"HND\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Handover package. Filled mainly by R3, areas.\"\n        },\n        \"LCY\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Lifecycle: release, maintenance, repair, end of life. Filled mainly by R4.\"\n        },\n        \"PLW\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Planetary weight ledger, accumulating from F5 to R4. Filled mainly by F5, S-areas, T9, R4.\"\n        },\n        \"DOS\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n          \"description\": \"Dossier: evidence, alternatives, abandoned directions, future practice. Filled mainly by R5.\"\n        },\n        \"SITE\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"#/$defs/entry\"\n          },\n",
"          \"description\": \"The site, object, body or brand pack a studio brief runs on. Filled mainly by Areas at Mastery.\"\n        },\n        \"SRC\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"$ref\": \"src-entry.schema.json\"\n          },\n          \"description\": \"Sources, attributions, consultation record. Filled mainly by F1, M1, R2.\"\n        },\n        \"GRM\": {\n          \"type\": \"object\",\n          \"additionalProperties\": false,\n          \"description\": \"Grammars. Candidates from F2–F4; rules in M2; refined in areas.\",\n          \"properties\": {\n            \"f\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"formal grammar (GRM.f)\"\n            },\n            \"m\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"material grammar (GRM.m)\"\n            },\n            \"k\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"construction grammar (GRM.k)\"\n            },\n",
"            \"c\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"chromatic grammar (GRM.c)\"\n            },\n            \"s\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"spatial grammar (GRM.s)\"\n            },\n            \"a\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"atmospheric grammar (GRM.a)\"\n            },\n            \"sn\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"sensory grammar (GRM.sn)\"\n            },\n            \"b\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"behavioural grammar (GRM.b)\"\n            },\n            \"i\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n",
"              \"description\": \"interaction grammar (GRM.i)\"\n            },\n            \"t\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"temporal grammar (GRM.t)\"\n            },\n            \"n\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"narrative grammar (GRM.n)\"\n            },\n            \"v\": {\n              \"type\": \"array\",\n              \"items\": {\n                \"$ref\": \"#/$defs/entry\"\n              },\n              \"description\": \"verbal grammar (GRM.v)\"\n            }\n          }\n        }\n      }\n    }\n  },\n  \"$defs\": {\n    \"entry\": {\n      \"type\": \"object\",\n      \"required\": [\n        \"unit\",\n        \"lane\",\n        \"depth\",\n        \"text\"\n      ],\n      \"additionalProperties\": false,\n      \"properties\": {\n        \"unit\": {\n          \"type\": \"string\",\n          \"pattern\": \"^[A-Z][0-9]{1,2}(\\\\.[0-9]{1,2}[a-z]?)?$\",\n          \"description\": \"The unit that wrote the entry, e.g. F1.14\"\n        },\n        \"lane\": {\n          \"enum\": [\n            \"M\",\n            \"B\"\n          ]\n",
"        },\n        \"depth\": {\n          \"enum\": [\n            \"O\",\n            \"P\",\n            \"M\"\n          ]\n        },\n        \"text\": {\n          \"type\": \"string\",\n          \"minLength\": 1\n        },\n        \"sources\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"string\"\n          },\n          \"description\": \"SRC entry ids this entry relies on\"\n        },\n        \"confidence\": {\n          \"enum\": [\n            \"documented\",\n            \"probable\",\n            \"contested\",\n            \"interpretive\"\n          ]\n        },\n        \"written\": {\n          \"type\": \"string\",\n          \"format\": \"date\"\n        },\n        \"version\": {\n          \"type\": \"integer\",\n          \"minimum\": 1\n        }\n      }\n    }\n  },\n  \"x-field-order\": [\n    \"SRC\",\n    \"PRM\",\n    \"PER\",\n    \"RUL\",\n    \"ANT\",\n    \"GRM\",\n    \"ALN\",\n    \"OBL\",\n    \"TST\",\n    \"BRF\",\n    \"VER\",\n    \"COL\",\n    \"ANC\",\n    \"ADJ\",\n    \"JDG\",\n    \"CMB\",\n    \"VEN\",\n    \"RGT\",\n    \"HND\",\n    \"LCY\",\n    \"PLW\",\n    \"DOS\",\n    \"SITE\"\n  ],\n  \"x-grammar-codes\": {\n    \"f\": \"formal\",\n    \"m\": \"material\",\n    \"k\": \"construction\",\n    \"c\": \"chromatic\",\n    \"s\": \"spatial\",\n    \"a\": \"atmospheric\",\n",
"    \"sn\": \"sensory\",\n    \"b\": \"behavioural\",\n    \"i\": \"interaction\",\n    \"t\": \"temporal\",\n    \"n\": \"narrative\",\n    \"v\": \"verbal\"\n  }\n}"
]
