"licence-classes.json",
[
"{\n  \"description\": \"The licence switch (decision Q39). Every asset carries one class; one dataset makes two builds. Implemented in modules/F1-histories-of-making/atlas/tools/licence_class.py.\",\n  \"classes\": [\n    {\n      \"code\": \"PD-CC0\",\n      \"meaning\": \"Public domain, CC0 or 'no known copyright' as the holder states it\",\n      \"open_build\": \"host\",\n      \"commercial_build\": \"host\"\n    },\n    {\n      \"code\": \"NATIONAL-OPEN\",\n      \"meaning\": \"A national open licence: KOGL Type 1, Japan Government Standard Terms and similar\",\n      \"open_build\": \"host\",\n      \"commercial_build\": \"host\"\n    },\n    {\n      \"code\": \"ATTRIBUTION\",\n      \"meaning\": \"CC BY or CC BY-SA; credit required\",\n      \"open_build\": \"host\",\n      \"commercial_build\": \"host\"\n    },\n    {\n      \"code\": \"OWN\",\n      \"meaning\": \"Our own drawing, diagram, map, photograph or translation\",\n      \"open_build\": \"host\",\n      \"commercial_build\": \"host\"\n    },\n    {\n      \"code\": \"PERMISSION-NC\",\n      \"meaning\": \"Non-commercial licence or permission-only; hostable only with a holder's free educational grant\",\n      \"open_build\": \"host if granted, else link\",\n      \"commercial_build\": \"link; use the recorded fallback\"\n",
"    },\n    {\n      \"code\": \"LINK-ONLY\",\n      \"meaning\": \"In copyright, ND, unclear or restricted by the holder's own rules\",\n      \"open_build\": \"link\",\n      \"commercial_build\": \"link\"\n    }\n  ],\n  \"rules\": [\n    \"An old date or an anonymous maker proves nothing: the licence is read per record from the holder.\",\n    \"Every PERMISSION-NC item records a fallback (another object, our own drawing, a living practice or a link).\",\n    \"No generated images of historical objects, people or places, in any class (Q32).\"\n  ]\n}"
]
],
