"program.json",
[
"{\n  \"name\": \"Creative World\",\n  \"description\": \"A self-paced design-education program on world-building for makers and the people who brief them. Two lanes in every unit (Maker, Briefer); three depths (Orientation, Practice, Mastery); every learner builds one artifact, the Concept DNA.\",\n  \"source\": \"Master Structure v2.1 (docs/01-structure/master-structure-v2.1-pass-1) and Final Structure v3.0; F1 at structure v3.6 per the Program Hub\",\n  \"lanes\": {\n    \"M\": \"Maker\",\n    \"B\": \"Briefer\"\n  },\n  \"depths\": {\n    \"O\": \"Orientation\",\n    \"P\": \"Practice\",\n    \"M\": \"Mastery\"\n  },\n  \"routes\": [\n    \"Maker\",\n    \"Briefer\",\n    \"Founder\",\n    \"Student\"\n  ],\n  \"gates\": {\n    \"G1\": \"Structure approved (passed 2026-09-28)\",\n    \"G2\": \"Experience design: Atlas logic and mockups\",\n    \"G3\": \"Unit specs and data fact-checked\"\n  },\n  \"levels\": [\n    {\n      \"level\": 0,\n      \"name\": \"Orientation\",\n      \"modules\": [\n        {\n          \"code\": \"O1\",\n          \"title\": \"How to see\",\n          \"units\": 4\n        }\n      ]\n    },\n    {\n      \"level\": 1,\n      \"name\": \"Foundations\",\n      \"modules\": [\n        {\n          \"code\": \"F1\",\n          \"title\": \"Histories of making\",\n          \"units\": 35,\n",
"          \"version\": \"v3.6\",\n          \"status\": \"phase 4: specs batch 1 done\",\n          \"folder\": \"modules/F1-histories-of-making\"\n        },\n        {\n          \"code\": \"F2\",\n          \"title\": \"Form\",\n          \"units\": 15\n        },\n        {\n          \"code\": \"F3\",\n          \"title\": \"Body and senses\",\n          \"units\": 13\n        },\n        {\n          \"code\": \"F4\",\n          \"title\": \"Material and meaning\",\n          \"units\": 14\n        },\n        {\n          \"code\": \"F5\",\n          \"title\": \"Systems and consequences\",\n          \"units\": 11\n        }\n      ]\n    },\n    {\n      \"level\": 2,\n      \"name\": \"Method\",\n      \"modules\": [\n        {\n          \"code\": \"M1\",\n          \"title\": \"Research and premise\",\n          \"units\": 16\n        },\n        {\n          \"code\": \"M2\",\n          \"title\": \"Concept DNA\",\n          \"units\": 20\n        },\n        {\n          \"code\": \"M3\",\n          \"title\": \"World architecture\",\n          \"units\": 10\n        },\n        {\n          \"code\": \"M4\",\n          \"title\": \"Make and test\",\n          \"units\": 12\n        }\n      ]\n    },\n    {\n      \"level\": 3,\n      \"name\": \"Practice areas\",\n      \"modules\": [\n        {\n          \"code\": \"S1\",\n",
"          \"title\": \"Space and experience\",\n          \"units\": 34\n        },\n        {\n          \"code\": \"S2\",\n          \"title\": \"Object and product\",\n          \"units\": 40\n        },\n        {\n          \"code\": \"S3\",\n          \"title\": \"Body and wearables\",\n          \"units\": 46\n        },\n        {\n          \"code\": \"S4\",\n          \"title\": \"Art and installation\",\n          \"units\": 37\n        },\n        {\n          \"code\": \"S5\",\n          \"title\": \"Identity and communication\",\n          \"units\": 24\n        },\n        {\n          \"code\": \"S6\",\n          \"title\": \"Digital product and interface\",\n          \"units\": 20\n        }\n      ]\n    },\n    {\n      \"level\": \"T\",\n      \"name\": \"Tools\",\n      \"modules\": [\n        {\n          \"code\": \"T1\",\n          \"title\": \"Seeing and drawing\",\n          \"units\": 5\n        },\n        {\n          \"code\": \"T2\",\n          \"title\": \"Parametric thinking\",\n          \"units\": 5\n        },\n        {\n          \"code\": \"T3\",\n          \"title\": \"Working with AI\",\n          \"units\": 5\n        },\n        {\n          \"code\": \"T4\",\n          \"title\": \"Simulation and interface\",\n          \"units\": 5\n        },\n        {\n          \"code\": \"T5\",\n",
"          \"title\": \"Honest evidence\",\n          \"units\": 4\n        },\n        {\n          \"code\": \"T6\",\n          \"title\": \"Reality capture\",\n          \"units\": 3\n        },\n        {\n          \"code\": \"T7\",\n          \"title\": \"Data visualisation\",\n          \"units\": 4\n        },\n        {\n          \"code\": \"T8\",\n          \"title\": \"Physical computing\",\n          \"units\": 4\n        },\n        {\n          \"code\": \"T9\",\n          \"title\": \"Environmental analytics\",\n          \"units\": 2\n        },\n        {\n          \"code\": \"T10\",\n          \"title\": \"Fabrication\",\n          \"units\": 3\n        }\n      ]\n    },\n    {\n      \"level\": 4,\n      \"name\": \"Venture and release\",\n      \"modules\": [\n        {\n          \"code\": \"R1\",\n          \"title\": \"The world as venture\",\n          \"units\": 12\n        },\n        {\n          \"code\": \"R2\",\n          \"title\": \"Money, law and rights\",\n          \"units\": 11\n        },\n        {\n          \"code\": \"R3\",\n          \"title\": \"Making it real\",\n          \"units\": 12\n        },\n        {\n          \"code\": \"R4\",\n          \"title\": \"Responsibility\",\n          \"units\": 8\n        },\n        {\n          \"code\": \"R5\",\n          \"title\": \"Defence and dossier\",\n",
"          \"units\": 9\n        }\n      ]\n    }\n  ],\n  \"threads\": [\n    {\n      \"name\": \"Planetary Weight\",\n      \"owner\": \"Planetary Ledger\"\n    },\n    {\n      \"name\": \"Handover Grammar\",\n      \"owner\": \"Handover Auditor\"\n    },\n    {\n      \"name\": \"Attribution and Authority\",\n      \"owner\": \"Historian voice\"\n    },\n    {\n      \"name\": \"Accessibility\",\n      \"owner\": \"Accessibility Checker\"\n    },\n    {\n      \"name\": \"Writing and Argument\",\n      \"owner\": \"Defence Room\"\n    },\n    {\n      \"name\": \"AI Collaboration\",\n      \"owner\": \"Stranger Lab\"\n    }\n  ],\n  \"partner_voices\": {\n    \"Historian\": \"records keep the names of those who ordered, paid or signed; asks who drew the line and when\",\n    \"Mirror\": \"reflects the learner's own choices back; never tells them they are wrong\",\n    \"Client\": \"speaks for the commissioner's constraints\",\n    \"Fabricator\": \"speaks for the maker, material and process\",\n    \"Planet\": \"speaks for planetary weight\",\n    \"Stranger\": \"speaks for the user or community outside the brief\"\n  },\n  \"presentation_forms\": {\n    \"1\": \"scrollytelling\",\n    \"2\": \"step-through\",\n    \"3\": \"object story\",\n    \"4\": \"explorable\",\n    \"5\": \"before/after\",\n    \"7\": \"video\",\n",
"    \"8\": \"audio\",\n    \"10\": \"comparison wall\",\n    \"11\": \"timeline scrub\",\n    \"12\": \"map\",\n    \"13\": \"argument card\",\n    \"14\": \"sequential illustration\",\n    \"15\": \"prediction prompt\"\n  },\n  \"notes\": \"Unit counts are from Master Structure v2.1 except F1 (v3.6 per the Hub). Threads are from Final Structure v3.0, 'The six threads'. Partner-voice agendas are one-line summaries; the voice packs are authoritative (only the Historian pack exists so far).\"\n}"
]
