"{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://github.com/creative-world/schema/src-entry.schema.json\",\n  \"title\": \"Sources record (SRC) entry\",\n  \"description\": \"The learner's own record of one thing their world draws on. Grows with depth: nine fields at Orientation, thirteen at Practice, sixteen at Mastery (Phase 4 Foundations, option C). Borrows RightsStatements.org, Local Contexts, Oral History Association practice, Getty/Pleiades/Wikidata and Dublin Core.\",\n  \"type\": \"object\",\n  \"required\": [\n    \"id\",\n    \"what\",\n    \"title\",\n    \"made_by\",\n    \"when\",\n    \"where\",\n    \"found_at\",\n    \"rights\",\n    \"relation\",\n    \"consultation\"\n  ],\n  \"properties\": {\n    \"id\": {\n      \"type\": \"string\"\n    },\n    \"what\": {\n      \"enum\": [\n        \"object\",\n        \"text\",\n        \"image\",\n        \"recording\",\n        \"practice\",\n        \"person-or-interview\",\n        \"dataset\",\n        \"site\"\n      ],\n      \"x-depth\": \"O\"\n    },\n    \"title\": {\n      \"type\": \"string\",\n      \"x-depth\": \"O\"\n    },\n    \"made_by\": {\n      \"type\": \"object\",\n      \"x-depth\": \"O\",\n",
"      \"description\": \"Named maker, unnamed workshop, community (its own name for itself first), institution\",\n      \"properties\": {\n        \"kind\": {\n          \"enum\": [\n            \"named-maker\",\n            \"unnamed-workshop\",\n            \"community\",\n            \"institution\",\n            \"not-known\"\n          ]\n        },\n        \"name\": {\n          \"type\": \"string\"\n        },\n        \"own_name\": {\n          \"type\": \"string\"\n        }\n      }\n    },\n    \"when\": {\n      \"type\": \"object\",\n      \"x-depth\": \"O\",\n      \"properties\": {\n        \"earliest\": {\n          \"type\": [\n            \"integer\",\n            \"null\"\n          ]\n        },\n        \"latest\": {\n          \"type\": [\n            \"integer\",\n            \"null\"\n          ]\n        },\n        \"as_written\": {\n          \"type\": \"string\"\n        }\n      }\n    },\n    \"where\": {\n      \"type\": \"object\",\n      \"x-depth\": \"O\",\n      \"properties\": {\n        \"historical_name\": {\n          \"type\": \"string\"\n        },\n        \"modern_name\": {\n          \"type\": \"string\"\n        },\n        \"identifier\": {\n          \"type\": \"string\",\n          \"description\": \"Pleiades, Getty TGN or Wikidata id, from a harvest, never typed\"\n        }\n",
"      }\n    },\n    \"found_at\": {\n      \"type\": \"string\",\n      \"x-depth\": \"O\",\n      \"description\": \"Link, accession number, DOI or Wikidata id\"\n    },\n    \"rights\": {\n      \"type\": \"object\",\n      \"x-depth\": \"O\",\n      \"required\": [\n        \"statement\",\n        \"checked\"\n      ],\n      \"properties\": {\n        \"statement\": {\n          \"type\": \"string\",\n          \"description\": \"A Creative Commons licence or a RightsStatements.org statement, never free text\"\n        },\n        \"licence_class\": {\n          \"enum\": [\n            \"PD-CC0\",\n            \"NATIONAL-OPEN\",\n            \"ATTRIBUTION\",\n            \"OWN\",\n            \"PERMISSION-NC\",\n            \"LINK-ONLY\"\n          ]\n        },\n        \"checked\": {\n          \"type\": \"string\",\n          \"format\": \"date\"\n        }\n      }\n    },\n    \"relation\": {\n      \"type\": \"object\",\n      \"x-depth\": \"O\",\n      \"description\": \"Position on the F1.2 plane and the harm axis\",\n      \"properties\": {\n        \"position\": {\n          \"enum\": [\n            \"reference\",\n            \"quotation\",\n            \"adaptation\",\n            \"translation\",\n            \"appropriation\"\n          ]\n        },\n        \"harm\": {\n          \"enum\": [\n",
"            \"none\",\n            \"low\",\n            \"medium\",\n            \"high\",\n            \"severe\",\n            \"for-the-community-to-name\"\n          ]\n        }\n      }\n    },\n    \"consultation\": {\n      \"enum\": [\n        \"no\",\n        \"yes-not-yet-asked\",\n        \"asked\",\n        \"granted\",\n        \"declined\"\n      ],\n      \"x-depth\": \"O\"\n    },\n    \"attribution_line\": {\n      \"type\": \"string\",\n      \"x-depth\": \"P\"\n    },\n    \"protocol\": {\n      \"type\": \"object\",\n      \"x-depth\": \"P\",\n      \"properties\": {\n        \"notice_or_label\": {\n          \"type\": \"string\",\n          \"description\": \"Local Contexts Notice or Label\"\n        },\n        \"sensitivity\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"enum\": [\n              \"sacred\",\n              \"ancestral\",\n              \"funerary\",\n              \"restricted\"\n            ]\n          }\n        },\n        \"care_note\": {\n          \"type\": \"string\"\n        }\n      }\n    },\n    \"credibility\": {\n      \"type\": \"object\",\n      \"x-depth\": \"P\",\n      \"description\": \"Source Grader result\",\n      \"properties\": {\n        \"provenance\": {\n          \"type\": \"string\"\n        },\n        \"bias\": {\n          \"type\": \"string\"\n",
"        },\n        \"distance\": {\n          \"type\": \"string\"\n        },\n        \"corroboration\": {\n          \"type\": \"string\"\n        }\n      }\n    },\n    \"used_in\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"string\"\n      },\n      \"x-depth\": \"P\",\n      \"description\": \"Artifact fields and units that draw on it\"\n    },\n    \"consent_record\": {\n      \"type\": \"object\",\n      \"x-depth\": \"M\",\n      \"properties\": {\n        \"form\": {\n          \"type\": \"string\"\n        },\n        \"review_status\": {\n          \"type\": \"string\"\n        },\n        \"restrictions\": {\n          \"type\": \"string\"\n        },\n        \"withdrawal_route\": {\n          \"type\": \"string\"\n        }\n      }\n    },\n    \"consultation_record\": {\n      \"type\": \"object\",\n      \"x-depth\": \"M\",\n      \"properties\": {\n        \"who\": {\n          \"type\": \"string\"\n        },\n        \"when\": {\n          \"type\": \"string\"\n        },\n        \"agreed\": {\n          \"type\": \"string\"\n        },\n        \"credit\": {\n          \"type\": \"string\"\n        },\n        \"given_back\": {\n          \"type\": \"string\"\n        }\n      }\n    },\n    \"versions\": {\n      \"type\": \"array\",\n      \"x-depth\": \"M\",\n      \"items\": {\n        \"type\": \"object\",\n",
"        \"properties\": {\n          \"date\": {\n            \"type\": \"string\"\n          },\n          \"note\": {\n            \"type\": \"string\"\n          }\n        }\n      }\n    }\n  }\n}"
]
]
